[8558] = { en = "Sickle of Unyielding Strength", tier = 4,
  t = "Sickle of Unyielding Strength",
  d = "De Qiraji en hun dienaren gebruiken voorwerpen van de zeldzaamste en beste materialen: botten van reusachtige oeroude wezens, edelstenen uit de diepten van de aarde, zuiver en sterk metaal.$B$BAls ik Qiraji-voorwerpen alleen al zie, wil ik mijn vak uitoefenen met hun gebroken en omgesmolten stukken. Bewijs je trouw aan de Circle, $N, dan maak ik een krachtig wapen voor je van de beste Qiraji-materialen.",
  o = "Breng 1 Qiraji Spiked Hilt, 2 Alabaster Idols, 5 Crystal Scarabs en 5 Stone Scarabs naar Warden Haro in Silithus. Je moet ook de reputatie Exalted bij de Cenarion Circle bereiken om deze quest af te maken.",
  p = "Heb je de onderdelen meegebracht die ik nodig heb, $N?",
  c = "Goed gedaan, $C. Dit is een meesterlijk gevest... het evenwicht is perfect.$B$BNeem je wapen, $N. Hanteer het met groot vertrouwen en versla onze vijanden!",
  g = { {"dienaren", "servants (dienaar)"}, {"zeldzaamste", "rarest (zeldzaam)"}, {"reusachtige", "gargantuan, giant (reusachtig)"}, {"oeroude", "ancient (oeroud)"}, {"diepten", "depths (diepte)"}, {"uitoefenen", "to practise (a craft)"}, {"omgesmolten", "smelted down (omsmelten)"}, {"trouw", "loyalty, allegiance"}, {"onderdelen", "components, parts (onderdeel)"}, {"meesterlijk", "masterly, masterwork"}, {"gevest", "hilt"}, {"evenwicht", "balance"}, {"Hanteer", "wield (hanteren)"}, {"vertrouwen", "confidence, trust"}, {"versla", "vanquish, defeat (verslaan)"} },
},

[8559] = { en = "Conqueror's Greaves", tier = 4,
  t = "Conqueror's Greaves",
  d = "De magie van de Qiraji is sterk en oeroud. De machtigste Qiraji gebruiken voorwerpen met zoveel kracht dat zelfs een draak zou aarzelen.$B$BBreng me de Qiraji Bindings of Command en nog wat kleinere onderdelen. Dan maak ik een paar krachtige laarzen voor je.$B$BJe zult er veel aan hebben in de strijd tegen de vijand.",
  o = "Breng de Qiraji Bindings of Command, 2 Idols of War, 5 Ivory Scarabs en 5 Gold Scarabs naar Kandrostrasz in Ahn'Qiraj. Voor deze quest heb je ook de reputatie Neutral bij het Brood of Nozdormu nodig.",
  p = "Heb je de spullen die ik vroeg, $N?",
  c = "Goed gedaan, $N. Je hebt bewezen dat je geen gewone sterveling bent.$B$BIk geef je deze in het vertrouwen dat ze je zullen helpen de walgelijke Qiraji te verpletteren.",
  g = { {"oeroud", "ancient"}, {"machtigste", "most powerful (machtig)"}, {"voorwerpen", "items, objects (voorwerp)"}, {"aarzelen", "to hesitate, pause"}, {"onderdelen", "components (onderdeel)"}, {"laarzen", "boots (laars)"}, {"sterveling", "mortal"}, {"bewezen", "proven (bewijzen)"}, {"in het vertrouwen", "with the confidence, trusting"}, {"walgelijke", "vile, disgusting (walgelijk)"}, {"verpletteren", "to crush"} },
},

[8560] = { en = "Conqueror's Legguards", tier = 4,
  t = "Conqueror's Legguards",
  d = "Wil je je waarde bewijzen aan mijn soort, sterveling? Goed dan. Misschien kunnen we elkaar helpen.$B$BDe oeroude zandworm Ouro is een wezen met legendarische kracht. Men zegt dat de Old God zelf hem heeft geschapen, als een bespotting van het leven.$B$BZijn huid is onnatuurlijk... dik en bijna ondoordringbaar. Toch is ze soepel. Daardoor kan hij zich bewegen met de snelheid en de gratie van een veel kleiner wezen.$B$BBreng me een stukje van zijn huid en nog wat kleinere onderdelen. Dan maak ik voor jou beenstukken met grote kracht.",
  o = "Breng Ouro's Intact Hide, 2 Idols of Death, 5 Bronze Scarabs en 5 Ivory Scarabs naar Kandrostrasz binnen in Ahn'Qiraj. Je moet ook de reputatie Friendly bij het Brood of Nozdormu bereiken om deze quest af te maken.",
  p = "Heb je de onderdelen meegebracht die ik nodig heb, $N?",
  c = "Ja... de huid van de worm wordt een uitstekende beschermende laag. Samen met de sterkste delen van de Qiraji die we onderweg hierheen hebben vernietigd, wordt dit een indrukwekkend stuk harnas. Moge het je helpen tegen de onbeschrijfelijke verschrikkingen die binnen op je wachten!",
  g = { {"sterveling", "mortal"}, {"oeroude", "ancient (oeroud)"}, {"zandworm", "sandworm"}, {"legendarische", "legendary"}, {"Men zegt", "it is rumored"}, {"geschapen", "created (scheppen)"}, {"bespotting", "mockery"}, {"onnatuurlijk", "unnatural"}, {"ondoordringbaar", "impregnable"}, {"soepel", "flexible, supple"}, {"gratie", "grace"}, {"beenstukken", "leggings, leg armor (beenstuk)"}, {"indrukwekkend", "formidable, impressive"}, {"onbeschrijfelijke", "unspeakable, indescribable"}, {"verschrikkingen", "horrors (verschrikking)"} },
},

[8561] = { en = "Conqueror's Crown", tier = 4,
  t = "Conqueror's Crown",
  d = "De Twin Emperors... hun eindeloze gefluister tast langzaam mijn verstand aan. Ze bespotten me, omdat ze weten dat ik niet verder hun gebied in kan gaan om mijn broer Arygos te redden.$B$BIn mijn visioenen zie ik hun monsterlijke gezichten, versierd met machtige kronen. Maar ik zal wraak nemen... Ik zal deze symbolen van Qiraji-macht omvormen tot symbolen die beter bij onze behoeften passen.$B$BBreng me de onderdelen die ik nodig heb, $N. Ik maak je een hoofddeksel met ongeëvenaarde kracht.",
  o = "Breng Vek'nilash's Circlet, 2 Idols of the Sun, 5 Stone Scarabs en 5 Crystal Scarabs naar Andorgos in Ahn'Qiraj. Je moet ook de reputatie Friendly bij het Brood of Nozdormu bereiken om deze quest af te maken.",
  p = "Heb je de onderdelen meegebracht waar ik om vroeg, $N?",
  c = "Het is je gelukt! Het gefluister van de Twin Emperors is opgehouden.$B$BNeem dit als beloning. Alleen al de aanblik ervan zal angst zaaien in de harten van de Qiraji... Het zal hen herinneren aan hun gevallen leiders en aan de sterveling die hen heeft gedood.",
  g = { {"eindeloze", "incessant, endless (eindeloos)"}, {"gefluister", "whispers, whispering"}, {"tast", "affects, erodes (aantasten)"}, {"verstand", "sanity, mind"}, {"bespotten", "mock"}, {"visioenen", "visions (visioen)"}, {"versierd", "adorned (versieren)"}, {"omvormen", "to transmute, transform"}, {"behoeften", "needs (behoefte)"}, {"hoofddeksel", "headpiece"}, {"ongeëvenaarde", "unmatched (ongeëvenaard)"}, {"opgehouden", "ceased (ophouden)"}, {"aanblik", "sight"}, {"angst zaaien", "to strike fear"} },
},

[8562] = { en = "Conqueror's Breastplate", tier = 4,
  t = "Conqueror's Breastplate",
  d = "De onnoembare Old God ontwaakt langzaam uit zijn slaap onder Ahn'Qiraj. Het vreselijke lot dat Azeroth wacht, kan over dagen of over jaren komen. Tijd betekent niets voor wezens met zijn macht.$B$BAls de sterren gunstig staan, slaat hij met verschrikkelijke woede toe tegen alle levende wezens. Je moet hem vóór die tijd vinden. Zoek een manier om een einde te maken aan zijn bestaan.$B$BDoe dit en breng me een stuk van zijn omhulsel. Dan geef ik je een harnas dat nog geen sterveling ooit heeft gedragen... een harnas dat past bij iemand die een god heeft gedood!",
  o = "Breng de Carapace of the Old God, 2 Idols of War, 5 Silver Scarabs en 5 Bone Scarabs naar Vethsera binnen in Ahn'Qiraj. Je moet ook de reputatie Honored bij het Brood of Nozdormu bereiken om deze quest af te maken.",
  p = "In zijn verblijf in Ahn'Qiraj ligt de gevreesde C'Thun te slapen en te wachten.",
  c = "Ik had niet verwacht dat je van je poging zou terugkeren, $N.$B$BJe hebt een lot vervuld dat groter is dan dat van de meeste onsterfelijke wezens.$B$BDoor C'Thun te doden heb je niet alleen heel Azeroth gered. Je hebt ook de weegschaal van kosmische gebeurtenissen laten doorslaan. Dat gaat je begrip te boven.$B$BNeem dit borstharnas aan als symbool van de glorie en de last die het gevolg van je daden zullen zijn.$B$BMoge zijn kracht je helpen bij de uitdagingen die op je wachten, godendoder!",
  g = { {"onnoembare", "unmentionable (onnoembaar)"}, {"ontwaakt", "awakens (ontwaken)"}, {"lot", "fate, destiny"}, {"gunstig", "favorable"}, {"woede", "wrath, anger"}, {"bestaan", "existence"}, {"omhulsel", "husk, shell"}, {"verblijf", "dwelling"}, {"gevreesde", "dread, feared (gevreesd)"}, {"vervuld", "fulfilled (vervullen)"}, {"onsterfelijke", "immortal (onsterfelijk)"}, {"weegschaal", "scales (for weighing)"}, {"laten doorslaan", "tipped (the scales)"}, {"gaat je begrip te boven", "is beyond your comprehension"}, {"godendoder", "god-slayer"} },
},

[8579] = { en = "Mortal Champions", tier = 4,
  t = "Mortal Champions",
  p = "We voelen de aanwezigheid van onze tot slaaf gemaakte broeders, dieper in Ahn'Qiraj. Toch zou zelfs een leger van draken niet genoeg zijn om hen te redden, $r.$B$BDezelfde spreuk die hen gevangen heeft gezet, zou ons volledig onder de macht van C'Thun brengen als we dichter bij hem kwamen.$B$BDe Old God heeft onze komst voorzien. Alle hoop is verloren. Wat voor verschil zou een eenvoudige sterveling als jij kunnen maken?",
  c = "Ik zie dat je geen gewone sterveling bent, $N. Je kansen tegen de Old God zijn oneindig klein. Toch zijn ze op dit moment groter dan de onze. Hij verwacht immers draken voor zijn deur, maar hij is niet voorbereid op iemand zoals jij.$B$BDuizend jaar geleden versloegen Anachronos en Staghelm de Qiraji door een verbond tussen de sterfelijke rassen en de drakenrassen. Net als zij zullen ook wij een pact sluiten. Win het vertrouwen van de Bronze Dragonflight, dan win je ook ons vertrouwen. Pas dan maken we een echte kampioen van je.",
  g = { {"aanwezigheid", "presence"}, {"tot slaaf gemaakte", "enslaved"}, {"broeders", "brethren (broeder)"}, {"spreuk", "spell"}, {"gevangen heeft gezet", "imprisoned (gevangenzetten)"}, {"voorzien", "foreseen (voorzien)"}, {"eenvoudige", "mere, simple (eenvoudig)"}, {"sterveling", "mortal"}, {"oneindig", "infinitely"}, {"immers", "after all"}, {"voorbereid", "prepared (voorbereiden)"}, {"verbond", "alliance, covenant"}, {"sterfelijke", "mortal (sterfelijk)"}, {"een pact sluiten", "to form a pact"}, {"kampioen", "champion"} },
},

